use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/fq6-toom175");let p=r.join("build-pins.json");let mut v:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();for f in["native.rs","native-helper","design.md","repair-link.rs","repin.rs"]{let p=r.join(f);v[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));}fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();}
